import{_ as o,o as a,c as e,aj as r}from"./chunks/framework.Cn87zHeG.js";const u=JSON.parse('{"title":"网络配置与 OTA","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"faq/network-ota.md","filePath":"faq/network-ota.md"}'),i={name:"faq/network-ota.md"};function l(d,t,n,s,h,q){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="网络配置与-ota" tabindex="-1">网络配置与 OTA <a class="header-anchor" href="#网络配置与-ota" aria-label="Permalink to &quot;网络配置与 OTA&quot;">​</a></h1><p><a href="/onerobot-H1/downloads/faq/network-ota-guide.pdf">下载《H1机器人网络配置和OTA功能使用文档》（PDF）</a></p><blockquote><p>使用网络配置工具需 H1 固件版本 <strong>不低于 1.0.017.260509</strong>。具体界面随固件变化；升级前请按<a href="./../firmware.html#查询设备已安装版本">固件版本查询</a>确认设备版本，并使用厂商提供的匹配升级包。</p></blockquote><p>当前最新整机版本见<a href="./../firmware.html">固件版本公告</a>。最低支持版本与当前最新版本含义不同。</p><h2 id="q12" tabindex="-1">Q12. 怎么打开机器人的网络配置工具？ <a class="header-anchor" href="#q12" aria-label="Permalink to &quot;Q12. 怎么打开机器人的网络配置工具？ {#q12}&quot;">​</a></h2><p>机器人自带本地 Web 配网工具（浏览器直接打开即可配 WiFi、看热点、改配置、升级 OTA），端口 <strong>8080</strong>，三种接入方式任选：</p><table tabindex="0"><thead><tr><th>接入方式</th><th>地址</th><th>场景</th></tr></thead><tbody><tr><td>网线直连</td><td><code>http://10.42.0.2:8080</code></td><td>开发 / 调试</td></tr><tr><td>机器人热点</td><td><code>http://192.168.60.1:8080</code></td><td>手机 / 笔记本无线</td></tr><tr><td>同一局域网</td><td><code>http://&lt;机器人IP&gt;:8080</code></td><td>机器人已连入 WiFi（IP 见&quot;状态&quot;页 WiFi 卡片）</td></tr></tbody></table><h2 id="q13" tabindex="-1">Q13. 机器人热点叫什么名字？有密码吗？ <a class="header-anchor" href="#q13" aria-label="Permalink to &quot;Q13. 机器人热点叫什么名字？有密码吗？ {#q13}&quot;">​</a></h2><ul><li>名称形如 <strong><code>H1_&lt;设备ID&gt;</code></strong>（例如 <code>H1_9CB8B496E710</code>），开机自动开启。</li><li><strong>未连过 WiFi 时</strong>：热点开放，无密码。</li><li><strong>连过 WiFi 后</strong>：热点密码自动同步为该 WiFi 的密码。</li><li><strong>断开 WiFi 后</strong>：热点恢复为无密码。</li><li>热点密码跟随 WiFi 自动同步，<strong>不需要也不支持手动修改</strong>。</li></ul><h2 id="q14" tabindex="-1">Q14. 怎么给机器人连接 WiFi？ <a class="header-anchor" href="#q14" aria-label="Permalink to &quot;Q14. 怎么给机器人连接 WiFi？ {#q14}&quot;">​</a></h2><p>进入「WiFi 配置」页 → 列表按信号强度排序 → 点目标网络右侧「连接」→ 输入密码 → 「连接」。连接成功会提示 <code>已成功连接到 &lt;SSID&gt;</code>。隐藏或扫不到的网络用「手动连接」，输入 SSID + 密码即可。</p><h2 id="q15" tabindex="-1">Q15. 连过的 WiFi 怎么管理 / 断开？ <a class="header-anchor" href="#q15" aria-label="Permalink to &quot;Q15. 连过的 WiFi 怎么管理 / 断开？ {#q15}&quot;">​</a></h2><ul><li><strong>管理</strong>：「WiFi 配置」页 →「已保存网络」标签，可直接复用（免再输密码）或删除。</li><li><strong>断开</strong>：「状态」页 → WiFi 连接卡片 →「断开」→ 确认。</li></ul><h2 id="q16" tabindex="-1">Q16. &quot;设备 ID&quot;和&quot;机器人 ID&quot;有什么区别？ <a class="header-anchor" href="#q16" aria-label="Permalink to &quot;Q16. &quot;设备 ID&quot;和&quot;机器人 ID&quot;有什么区别？ {#q16}&quot;">​</a></h2><ul><li><strong>设备 ID</strong>：从 wlan0 MAC 地址派生（去掉冒号、转大写），不可改，如 <code>9CB8B496E710</code>。</li><li><strong>机器人 ID</strong>：在「机器人配置」页可自定义填写的标识（如 <code>H1-XXXX-XXXX</code>），保存后可导出备份。</li></ul><h2 id="q17" tabindex="-1">Q17. 怎么做固件 OTA 升级？ <a class="header-anchor" href="#q17" aria-label="Permalink to &quot;Q17. 怎么做固件 OTA 升级？ {#q17}&quot;">​</a></h2><ol><li>进入「OTA 升级」页，把 <code>.img</code> 升级包拖入虚线框（或点击选择文件）上传。</li><li>上传完成后，在「已上传的 OTA 包」列表点对应包的「升级」→ 确认。</li><li>顶部横幅变<strong>橙色「正在升级中」</strong>，升级日志每秒刷新，直到出现 <strong><code>ota升级成功</code></strong>（弹绿色提示，机器人自动重启）或 <code>ota升级失败</code>。</li></ol><p>⚠️ <strong>升级期间严禁断电、严禁给机器人断电</strong>；橙色横幅期间不要做其它操作。</p><h2 id="q18" tabindex="-1">Q18. 升级过程中不小心刷新了页面 / 换了设备登录，会中断升级吗？ <a class="header-anchor" href="#q18" aria-label="Permalink to &quot;Q18. 升级过程中不小心刷新了页面 / 换了设备登录，会中断升级吗？ {#q18}&quot;">​</a></h2><p>不会。升级在机器人侧独立执行，重新打开页面会<strong>自动检测并恢复显示进度</strong>。<strong>但无论如何都不要给机器人断电。</strong></p><h2 id="q19" tabindex="-1">Q19. 点了升级后一直没反应怎么办？ <a class="header-anchor" href="#q19" aria-label="Permalink to &quot;Q19. 点了升级后一直没反应怎么办？ {#q19}&quot;">​</a></h2><p>如果 <strong>20 秒内没有任何状态反馈</strong>，工具会自动提示&quot;触发升级后无任何反馈&quot;并解除锁定，可重试。若多次无效，请联系厂商技术支持。</p>',22)])])}const g=o(i,[["render",l]]);export{u as __pageData,g as default};
